/// Low 32 bits of `a * b`. All partial products stay below 2^34, exact in a
/// float64, so the result is correct on every platform.
int _mul32(int a, int b) {
  final aLo = a & 0xFFFF;
  final aHi = a >>> 16;
  final bLo = b & 0xFFFF;
  final bHi = b >>> 16;
  final low = aLo * bLo;
  final mid = aHi * bLo + aLo * bHi;
  return _u32(low + ((mid & 0xFFFF) << 16));
}

