  final ms = DateTime.now().toUtc().millisecondsSinceEpoch;
  final rand =
      ((_secureRandom.nextInt(1 << 16) << 16) | _secureRandom.nextInt(1 << 16))
          .toRadixString(16)
          .padLeft(8, '0');
  return '$ms-${rand.substring(rand.length - 8)}';
}

